:root {
  --ink: #17120c;
  --brown: #2c2117;
  --brown-2: #3a2c1e;
  --cream: #f7ecd4;
  --cream-2: #e6d3ac;
  --amber: #ffb938;
  --amber-2: #ff8a1e;
  --green: #9ada63;
  --green-2: #5aa83c;
  --cyan: #7fe8ff;
  --red: #ff6b52;
  --panel: rgba(28, 21, 14, 0.86);
  --line: rgba(247, 236, 212, 0.16);
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0c0a07;
  color: var(--cream);
  font-family: 'Outfit', system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

#game { position: fixed; inset: 0; overflow: hidden; }
#view { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }

#depth-tint {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(ellipse at 50% 46%, rgba(0,0,0,0) 18%, rgba(2,4,10,0.38) 62%, rgba(1,2,7,0.9) 100%);
  transition: opacity 0.5s ease;
  z-index: 2;
}

.hidden { display: none !important; }

/* ---------- HUD ---------- */
#hud {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  padding: max(16px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
}

.hud-top {
  display: grid;
  grid-template-columns: minmax(150px, 200px) 1fr minmax(150px, 200px);
  align-items: start;
  gap: 14px;
}

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 11px 15px 12px;
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255,255,255,0.05);
  backdrop-filter: blur(8px);
}

.kicker {
  font-family: 'Silkscreen', monospace;
  font-size: 9px;
  letter-spacing: 0.14em;
  color: rgba(247,236,212,0.55);
}

.card .big {
  font-family: 'Silkscreen', monospace;
  font-size: clamp(22px, 2.5vw, 30px);
  line-height: 1.05;
  margin-top: 4px;
  letter-spacing: -0.02em;
}

.card .big .unit {
  font-size: 0.45em;
  margin-left: 4px;
  color: rgba(247,236,212,0.55);
  letter-spacing: 0;
}

.card .sub {
  font-size: 10px;
  letter-spacing: 0.09em;
  margin-top: 5px;
  color: rgba(247,236,212,0.48);
  font-weight: 600;
}

.depth-card { border-left: 3px solid var(--amber); }
.depth-card .big { color: var(--amber); }
.money-card { border-right: 3px solid var(--green); text-align: right; }
.money-card .big { color: var(--green); }
.money-card .currency { font-size: 0.62em; margin-right: 2px; color: rgba(154,218,99,0.8); }

.objective-card {
  justify-self: center;
  text-align: center;
  background: linear-gradient(180deg, #fdf3dd, #ecd9b3);
  color: #2b2014;
  border: 1px solid rgba(70,48,25,0.35);
  border-radius: 12px;
  padding: 8px 24px 9px;
  min-width: 240px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.35), inset 0 -3px 0 rgba(120,90,45,0.18);
  transition: transform 0.2s ease;
}
.objective-card.pop { animation: objpop 0.5s ease; }
@keyframes objpop { 0% { transform: scale(1); } 35% { transform: scale(1.07) rotate(-0.6deg); } 100% { transform: scale(1); } }
.obj-kicker {
  font-family: 'Silkscreen', monospace;
  font-size: 8px;
  letter-spacing: 0.16em;
  color: #8a6a3d;
}
.obj-text { font-weight: 800; font-size: 14px; line-height: 1.15; margin-top: 2px; }
.obj-reward {
  font-family: 'Silkscreen', monospace;
  font-size: 8px;
  letter-spacing: 0.08em;
  margin-top: 3px;
  color: #a35d12;
}

/* crosshair */
#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 48px;
  height: 48px;
  transform: translate(-50%, -50%);
  opacity: 0.9;
}
.ch-dot {
  position: absolute; left: 50%; top: 50%; width: 4px; height: 4px;
  margin: -2px 0 0 -2px; border-radius: 50%;
  background: var(--cream);
  box-shadow: 0 0 6px rgba(0,0,0,0.9);
}
.ch-line { position: absolute; background: rgba(247,236,212,0.85); box-shadow: 0 0 4px rgba(0,0,0,0.8); }
.ch-t, .ch-b { width: 2px; height: 6px; left: 23px; }
.ch-t { top: 4px; } .ch-b { bottom: 4px; }
.ch-l, .ch-r { height: 2px; width: 6px; top: 23px; }
.ch-l { left: 4px; } .ch-r { right: 4px; }
#crosshair.targeting .ch-line { background: var(--amber); }
#crosshair.targeting .ch-dot { background: var(--amber); }

#mine-ring { position: absolute; inset: 0; width: 48px; height: 48px; transform: rotate(-90deg); opacity: 0; transition: opacity 0.12s; }
#crosshair.mining #mine-ring { opacity: 1; }
#mine-ring circle { fill: none; stroke-width: 3; }
#mine-ring .ring-bg { stroke: rgba(0,0,0,0.35); }
#ring-fill {
  stroke: var(--amber);
  stroke-linecap: round;
  stroke-dasharray: 119.4;
  stroke-dashoffset: 119.4;
  filter: drop-shadow(0 0 4px rgba(255,185,56,0.8));
}

/* signal */
#signal {
  position: absolute;
  top: 104px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 14px;
  border-radius: 999px;
  background: rgba(30, 16, 5, 0.8);
  border: 1px solid rgba(255,185,56,0.35);
  box-shadow: 0 0 24px rgba(255,138,30,0.15);
  font-family: 'Silkscreen', monospace;
  font-size: 9px;
  letter-spacing: 0.08em;
  color: var(--amber);
}
.sig-diamond { animation: pulse 1.6s infinite; font-size: 12px; }
@keyframes pulse { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(0.82); } }
.sig-label { color: rgba(255,225,170,0.8); }
.sig-dist { color: #fff; }
.sig-arrow { font-size: 15px; transition: transform 0.12s linear; }

/* interact */
#interact-prompt {
  position: absolute;
  left: 50%;
  bottom: 148px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 16px 9px 10px;
  border-radius: 999px;
  background: rgba(24, 18, 12, 0.9);
  border: 1px solid rgba(247,236,212,0.24);
  box-shadow: var(--shadow);
  font-weight: 600;
  font-size: 13px;
  white-space: nowrap;
  animation: promptin 0.2s ease;
}
@keyframes promptin { from { opacity: 0; transform: translate(-50%, 6px); } }
.key {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 23px;
  height: 23px;
  padding: 0 6px;
  border-radius: 6px;
  background: linear-gradient(180deg, #fff4dc, #d9c39a);
  color: #2b2014;
  font-family: 'Silkscreen', monospace;
  font-size: 9px;
  font-weight: 700;
  box-shadow: 0 2px 0 #8f7854;
}

/* bottom hud */
.hud-bottom {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  right: max(18px, env(safe-area-inset-right));
  bottom: max(16px, env(safe-area-inset-bottom));
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
}
.pack-card { width: min(340px, 44vw); }
.pack-head {
  display: flex; justify-content: space-between; align-items: baseline;
  font-family: 'Silkscreen', monospace; font-size: 9px; letter-spacing: 0.1em;
  color: rgba(247,236,212,0.7);
}
.pack-bar {
  height: 9px; margin-top: 7px; border-radius: 999px;
  background: rgba(0,0,0,0.42);
  border: 1px solid rgba(247,236,212,0.12);
  overflow: hidden;
}
#pack-fill {
  height: 100%; width: 0%; border-radius: 999px;
  background: linear-gradient(90deg, #77c34a, #b6e86a);
  box-shadow: 0 0 10px rgba(154,218,99,0.45);
  transition: width 0.25s ease, background 0.3s;
}
#pack-fill.warn { background: linear-gradient(90deg, #ff9a2e, #ffd45c); box-shadow: 0 0 10px rgba(255,185,56,0.5); }
#pack-fill.full { background: linear-gradient(90deg, #ff5b3c, #ff9a6a); box-shadow: 0 0 12px rgba(255,107,82,0.6); }
#inv-chips { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 8px; min-height: 18px; }
.inv-chip {
  display: flex; align-items: center; gap: 4px;
  padding: 2px 6px 2px 3px; border-radius: 5px;
  background: rgba(0,0,0,0.32);
  border: 1px solid rgba(247,236,212,0.1);
  font-family: 'Silkscreen', monospace; font-size: 8px;
  color: rgba(247,236,212,0.85);
}
.inv-swatch { width: 10px; height: 10px; border-radius: 2px; box-shadow: inset 0 0 0 1px rgba(255,255,255,0.18); }

.drill-card { width: min(250px, 38vw); text-align: right; }
.drill-top { display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.winch-hint { font-size: 10px; color: rgba(247,236,212,0.5); display: flex; align-items: center; gap: 5px; font-weight: 600; }
.winch-hint .key { height: 18px; min-width: 18px; font-size: 8px; }
.drill-name {
  font-family: 'Silkscreen', monospace; font-size: 14px; letter-spacing: 0.02em;
  color: var(--cream); margin-top: 5px;
}
.drill-stats { display: flex; justify-content: flex-end; gap: 14px; font-size: 10px; color: rgba(247,236,212,0.5); margin-top: 3px; letter-spacing: 0.06em; }
.drill-stats b { color: var(--amber); font-family: 'Silkscreen', monospace; font-size: 9px; }

/* toasts */
#toasts {
  position: absolute;
  top: 150px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  width: min(90vw, 520px);
}
.toast {
  display: flex; align-items: center; gap: 9px;
  background: rgba(24, 18, 12, 0.94);
  border: 1px solid rgba(247,236,212,0.2);
  border-left: 3px solid var(--amber);
  padding: 8px 15px;
  border-radius: 9px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--cream);
  box-shadow: var(--shadow);
  animation: toastin 0.28s cubic-bezier(.2,1.3,.4,1);
  max-width: 100%;
}
.toast.out { animation: toastout 0.3s forwards; }
.toast.good { border-left-color: var(--green); }
.toast.bad { border-left-color: var(--red); }
.toast .t-big { font-family: 'Silkscreen', monospace; font-size: 11px; color: var(--amber); }
.toast.good .t-big { color: var(--green); }
.toast.bad .t-big { color: var(--red); }
@keyframes toastin { from { opacity: 0; transform: translateY(-8px) scale(0.96); } }
@keyframes toastout { to { opacity: 0; transform: translateY(-6px) scale(0.97); } }

/* ---------- Screens ---------- */
.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(ellipse at 50% 40%, rgba(8,6,4,0.18), rgba(8,6,4,0.8) 78%);
  padding: max(18px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
}

#screen-start {
  background: linear-gradient(100deg, rgba(9,7,5,0.94) 0%, rgba(9,7,5,0.82) 38%, rgba(9,7,5,0.28) 66%, rgba(9,7,5,0.55) 100%);
  justify-content: flex-start;
  padding-left: clamp(24px, 8vw, 120px);
}
.start-wrap { width: min(620px, 100%); }
.badge {
  display: inline-block;
  font-family: 'Silkscreen', monospace;
  font-size: 9px;
  letter-spacing: 0.18em;
  padding: 6px 11px;
  border-radius: 5px;
  background: rgba(255,185,56,0.14);
