  background: linear-gradient(180deg, rgba(255,201,87,0.95), rgba(245,154,31,0.95));
  color: #2a1a06; border-color: #ffd57e; font-size: 11px;
}
.mbtn.small { width: 56px; height: 56px; font-size: 8px; justify-self: end; }

/* responsive */
@media (max-width: 820px) {
  .hud-top { grid-template-columns: 1fr auto 1fr; gap: 8px; }
  .card { padding: 8px 10px 9px; border-radius: 10px; }
  .card .big { font-size: 18px; }
  .card .sub { display: none; }
  .objective-card { min-width: 0; padding: 6px 12px 7px; }
  .obj-text { font-size: 11px; }
  .obj-kicker { font-size: 7px; }
  .obj-reward { display: none; }
  .hud-bottom { flex-direction: column; align-items: stretch; gap: 8px; }
  .pack-card, .drill-card { width: 100%; }
  .drill-card { display: none; }
  .controls-grid { grid-template-columns: repeat(2, 1fr); }
  #screen-start { justify-content: center; padding-left: 22px; text-align: left; }
  .start-wrap { width: min(480px, 100%); }
  .smallprint { display: none; }
  #interact-prompt { bottom: 210px; }
  #signal { top: 78px; }
  .shop-panel { height: 92vh; }
  .sell-cols, .sell-row { grid-template-columns: 1fr 46px 76px; }
  .sell-cols span:nth-child(3), .sell-row .sell-unit { display: none; }
  .upgrade-grid { grid-template-columns: 1fr; }
  .pause-stats, .win-stats { grid-template-columns: repeat(2, 1fr); }
  .shop-head { padding: 12px 14px; gap: 10px; }
  .shop-body { padding: 12px; }
  .tabs { padding: 0 12px; }
  .sell-footer { flex-direction: column; align-items: stretch; }
  .sell-footer .btn { width: 100%; }
