function hash3(x, y, z) {
  let h = (x * 374761393 + y * 668265263 + z * 2147483647) | 0;
  h = (h ^ (h >>> 13)) * 1274126177;
  h = h ^ (h >>> 16);
  return ((h >>> 0) / 4294967295);
}

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hash2(ix, iz, seed) {
  let h = Math.imul(ix, 374761393) ^ Math.imul(iz, 668265263) ^ Math.imul(seed, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}

function smooth(t) { return t * t * (3 - 2 * t); }

function valueNoise2(x, z, seed) {
  const ix = Math.floor(x), iz = Math.floor(z);
  const fx = smooth(x - ix), fz = smooth(z - iz);
  const a = hash2(ix, iz, seed), b = hash2(ix + 1, iz, seed);
  const c = hash2(ix, iz + 1, seed), d = hash2(ix + 1, iz + 1, seed);
  return (a + (b - a) * fx) + ((c + (d - c) * fx) - (a + (b - a) * fx)) * fz;
}

function base64FromBytes(bytes) {
  let s = '';
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    s += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
  }
  return btoa(s);
}

function bytesFromBase64(str) {
  const bin = atob(str);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export class World {
  constructor(scene, seed = 1337) {
    this.scene = scene;
    this.seed = seed | 0;
    this.voxels = new Uint8Array(WORLD_X * WORLD_Y * WORLD_Z);
    this.surfaceHeights = new Int16Array(WORLD_X * WORLD_Z);
    this.chunkGroup = new THREE.Group();
    this.chunkGroup.name = 'voxel-world';
    this.scene.add(this.chunkGroup);
    this.chunks = new Map();
    this.dirty = new Set();
    this.coreBlock = new THREE.Vector3(0, SURFACE - 82, 0);
    this.corePos = new THREE.Vector3(0.5, SURFACE - 82 + 0.5, 0.5);
    this.coreLight = null;

    const atlas = createAtlas();
    this.material = new THREE.MeshLambertMaterial({
      map: atlas,
      vertexColors: true,
      fog: true,
    });
    this.material.name = 'voxel';
  }

  idx(x, y, z) {
    return (y * WORLD_Z + z) * WORLD_X + x;
  }

  inBounds(x, y, z) {
    return x >= 0 && x < WORLD_X && y >= 0 && y < WORLD_Y && z >= 0 && z < WORLD_Z;
  }

  get(x, y, z) {
    if (!this.inBounds(x, y, z)) return 0;
    return this.voxels[this.idx(x, y, z)];
  }

  isSolid(x, y, z) {
    if (y >= WORLD_Y) return false;
    if (x < 0 || x >= WORLD_X || z < 0 || z >= WORLD_Z || y < 0) return true;
    return this.voxels[this.idx(x, y, z)] !== 0;
  }

  set(x, y, z, block) {
    if (!this.inBounds(x, y, z)) return;
    this.voxels[this.idx(x, y, z)] = block;
    this.markDirty(x, y, z);
  }

  surfaceHeight(x, z) {
    const ix = Math.max(0, Math.min(WORLD_X - 1, Math.floor(x)));
    const iz = Math.max(0, Math.min(WORLD_Z - 1, Math.floor(z)));
    return this.surfaceHeights[iz * WORLD_X + ix];
  }

  // world coordinate (block centers are .5)
  topAt(x, z) {
    return this.surfaceHeight(x, z) + 1;
  }

  generate() {
    const rnd = mulberry32(this.seed);
    const vox = this.voxels;
    vox.fill(0);

    const heightNoiseSeed = (this.seed * 13 + 7) | 0;
    for (let x = 0; x < WORLD_X; x++) {
      for (let z = 0; z < WORLD_Z; z++) {
        const wx = x - WORLD_X / 2;
        const wz = z - WORLD_Z / 2;
        const edge = Math.max(Math.abs(wx), Math.abs(wz));
        const blend = Math.max(0, Math.min(1, (edge - 17) / 12));
        let h = SURFACE;
        if (blend > 0) {
          const n = valueNoise2(x * 0.075, z * 0.075, heightNoiseSeed) * 2.6 +
                    valueNoise2(x * 0.19, z * 0.19, heightNoiseSeed + 9) * 0.9;
          h += Math.round((n - 1.2) * blend * 1.6);
        }
        h = Math.max(SURFACE - 3, Math.min(SURFACE + 3, h));
        this.surfaceHeights[z * WORLD_X + x] = h;

        for (let y = 0; y <= h; y++) {
          const d = h - y;
          let b = BLOCK.STONE;
          if (y <= 1) b = BLOCK.BEDROCK;
          else if (d === 0) b = BLOCK.GRASS;
          else if (d <= 3) b = BLOCK.DIRT;
          else if (d <= 8) {
            const n = valueNoise2(x * 0.12, z * 0.12, this.seed + 31) + valueNoise2(x * 0.31, z * 0.31, this.seed + 77) * 0.5;
            b = n > 0.85 ? BLOCK.CLAY : (n < 0.55 ? BLOCK.GRAVEL : BLOCK.DIRT);
          } else if (d <= 24) {
            const n = valueNoise2(x * 0.09, z * 0.09, this.seed + 55) + valueNoise2(x * 0.27, z * 0.27, this.seed + 101) * 0.4;
            b = n > 1.05 ? BLOCK.CLAY : (n < 0.62 ? BLOCK.GRAVEL : BLOCK.STONE);
          } else if (d <= 46) {
            const n = valueNoise2(x * 0.08, z * 0.08, this.seed + 141);
            b = n > 0.72 ? BLOCK.GRAVEL : (n < 0.25 ? BLOCK.DEEPSTONE : BLOCK.STONE);
          } else {
            b = d > 54 && valueNoise2(x * 0.16, z * 0.16, this.seed + 201) > 0.7 ? BLOCK.STONE : BLOCK.DEEPSTONE;
          }
          if (d <= 10 && d > 3 && valueNoise2(x * 0.5, z * 0.5, this.seed + 303) > 0.82) b = BLOCK.MOSS;
          vox[this.idx(x, y, z)] = b;
        }
      }
    }

    // ore veins
    const plans = [
      { b: BLOCK.COAL, veins: 120, size: 9, d0: 3, d1: 26 },
      { b: BLOCK.COPPER, veins: 95, size: 8, d0: 7, d1: 38 },
      { b: BLOCK.IRON, veins: 80, size: 8, d0: 17, d1: 54 },
      { b: BLOCK.GOLD, veins: 55, size: 7, d0: 34, d1: 72 },
      { b: BLOCK.DIAMOND, veins: 34, size: 6, d0: 52, d1: 90 },
      { b: BLOCK.RUBY, veins: 18, size: 5, d0: 68, d1: 94 },
    ];
    for (const plan of plans) {
      for (let v = 0; v < plan.veins; v++) {
        let x = 3 + Math.floor(rnd() * (WORLD_X - 6));
        let z = 3 + Math.floor(rnd() * (WORLD_Z - 6));
        const h = this.surfaceHeights[z * WORLD_X + x];
        const depth = plan.d0 + rnd() * (plan.d1 - plan.d0);
        let y = Math.max(3, Math.min(WORLD_Y - 3, Math.round(h - depth)));
        const steps = 3 + Math.floor(rnd() * plan.size);
        for (let s = 0; s < steps; s++) {
          if (x > 1 && x < WORLD_X - 2 && z > 1 && z < WORLD_Z - 2 && y > 2 && y < WORLD_Y - 2) {
            const cur = vox[this.idx(x, y, z)];
            if (cur !== BLOCK.AIR && cur !== BLOCK.BEDROCK && cur !== BLOCK.CORE) {
              vox[this.idx(x, y, z)] = plan.b;
              // little satellite blob
              if (rnd() > 0.72) {
                const ox = rnd() > 0.5 ? 1 : -1;
                const oz = rnd() > 0.5 ? 1 : -1;
                const xx = x + ox, zz = z + oz;
                if (xx > 1 && xx < WORLD_X - 2 && zz > 1 && zz < WORLD_Z - 2) {
                  const c2 = vox[this.idx(xx, y, zz)];
                  if (c2 !== BLOCK.AIR && c2 !== BLOCK.BEDROCK) vox[this.idx(xx, y, zz)] = plan.b;
                }
              }
            }
          }
          const r = rnd();
          if (r < 0.34) x += rnd() > 0.5 ? 1 : -1;
          else if (r < 0.67) y += rnd() > 0.5 ? 1 : -1;
          else z += rnd() > 0.5 ? 1 : -1;
          x = Math.max(2, Math.min(WORLD_X - 3, x));
          z = Math.max(2, Math.min(WORLD_Z - 3, z));
          y = Math.max(2, Math.min(WORLD_Y - 3, y));
        }
      }
    }

    // caves
    for (let c = 0; c < 16; c++) {
      const cx = 6 + rnd() * (WORLD_X - 12);
      const cz = 6 + rnd() * (WORLD_Z - 12);
      const h = this.surfaceHeights[Math.floor(cz) * WORLD_X + Math.floor(cx)];
      const cy = h - (14 + rnd() * 58);
      const rx = 2.5 + rnd() * 3.4;
      const ry = 1.6 + rnd() * 2.2;
      const rz = 2.5 + rnd() * 3.4;
      // don't carve near the heart chamber
      if (Math.hypot(cx - WORLD_X / 2, cz - WORLD_Z / 2) < 11 && cy < SURFACE - 68) continue;
      for (let x = Math.floor(cx - rx - 1); x <= cx + rx + 1; x++) {
        for (let z = Math.floor(cz - rz - 1); z <= cz + rz + 1; z++) {
          for (let y = Math.floor(cy - ry - 1); y <= cy + ry + 1; y++) {
            if (!this.inBounds(x, y, z) || y <= 2) continue;
            const dx = (x - cx) / rx, dy = (y - cy) / ry, dz = (z - cz) / rz;
            const n = valueNoise2(x * 0.25 + y * 0.17, z * 0.25 - y * 0.11, this.seed + 404);
            if (dx * dx + dy * dy + dz * dz + (n - 0.5) * 0.55 < 1) {
              vox[this.idx(x, y, z)] = BLOCK.AIR;
            }
          }
        }
      }
    }

    // heart chamber
    const cx = WORLD_X / 2;
    const cz = WORLD_Z / 2;
    const coreY = SURFACE - 82;
    for (let x = Math.floor(cx) - 4; x <= Math.floor(cx) + 4; x++) {
      for (let z = Math.floor(cz) - 4; z <= Math.floor(cz) + 4; z++) {
        for (let y = coreY; y <= coreY + 4; y++) {
          if (this.inBounds(x, y, z)) vox[this.idx(x, y, z)] = BLOCK.AIR;
        }
      }
    }
    // shell with gems
    for (let x = Math.floor(cx) - 5; x <= Math.floor(cx) + 5; x++) {
      for (let z = Math.floor(cz) - 5; z <= Math.floor(cz) + 5; z++) {
        for (let y = coreY - 1; y <= coreY + 5; y++) {
          if (!this.inBounds(x, y, z)) continue;
          const edge = x === Math.floor(cx) - 5 || x === Math.floor(cx) + 5 || z === Math.floor(cz) - 5 || z === Math.floor(cz) + 5 || y === coreY - 1 || y === coreY + 5;
          if (!edge) continue;
          let b = y === coreY - 1 || y === coreY + 5 ? BLOCK.DEEPSTONE : BLOCK.DEEPSTONE;
          const r = rnd();
          if (r > 0.9) b = BLOCK.RUBY;
          else if (r > 0.72) b = BLOCK.DIAMOND;
          else if (r > 0.5) b = BLOCK.GOLD;
          else if (r > 0.34) b = BLOCK.IRON;
          vox[this.idx(x, y, z)] = b;
        }
      }
    }
    // floor gems
    for (let x = Math.floor(cx) - 4; x <= Math.floor(cx) + 4; x++) {
      for (let z = Math.floor(cz) - 4; z <= Math.floor(cz) + 4; z++) {
        const r = rnd();
        if (r > 0.72) vox[this.idx(x, coreY - 1, z)] = r > 0.94 ? BLOCK.RUBY : BLOCK.GOLD;
      }
    }
    const coreBlockY = coreY;
    const coreX = Math.floor(cx);
    const coreZ = Math.floor(cz);
    vox[this.idx(coreX, coreBlockY, coreZ)] = BLOCK.CORE;
    this.coreBlock.set(coreX, coreBlockY, coreZ);
    this.corePos.set(coreX + 0.5, coreBlockY + 0.5, coreZ + 0.5);

    // starter scrape: remove the grass over a 2x2 patch to invite digging
    for (let x = coreX - 1; x <= coreX; x++) {
      for (let z = coreZ - 1; z <= coreZ; z++) {
        const h = this.surfaceHeights[z * WORLD_X + x];
        vox[this.idx(x, h, z)] = BLOCK.AIR;
      }
    }

    this.rebuildAll();
  }

  // ---------- lighting / meshing ----------
  lightAt(x, y, z) {
    const ix = Math.max(0, Math.min(WORLD_X - 1, x));
    const iz = Math.max(0, Math.min(WORLD_Z - 1, z));
    const h = this.surfaceHeights[iz * WORLD_X + ix];
    const depth = Math.max(0, h - y);
    return Math.max(0.06, Math.min(1, 1 - depth / 27));
  }

  chunkKey(cx, cy, cz) { return cx + ',' + cy + ',' + cz; }

  markDirty(x, y, z) {
    const cx = Math.floor(x / CHUNK), cy = Math.floor(y / CHUNK), cz = Math.floor(z / CHUNK);
    this.dirty.add(this.chunkKey(cx, cy, cz));
    const lx = x % CHUNK, ly = y % CHUNK, lz = z % CHUNK;
    if (lx === 0) this.dirty.add(this.chunkKey(cx - 1, cy, cz));
    if (lx === CHUNK - 1) this.dirty.add(this.chunkKey(cx + 1, cy, cz));
    if (ly === 0) this.dirty.add(this.chunkKey(cx, cy - 1, cz));
    if (ly === CHUNK - 1) this.dirty.add(this.chunkKey(cx, cy + 1, cz));
    if (lz === 0) this.dirty.add(this.chunkKey(cx, cy, cz - 1));
    if (lz === CHUNK - 1) this.dirty.add(this.chunkKey(cx, cy, cz + 1));
  }

  flushDirty() {
    if (!this.dirty.size) return;
    for (const key of this.dirty) {
      const [cx, cy, cz] = key.split(',').map(Number);
      this.buildChunk(cx, cy, cz);
    }
    this.dirty.clear();
  }

  rebuildAll() {
    for (const key of this.chunks.keys()) {
      const [cx, cy, cz] = key.split(',').map(Number);
      this.buildChunk(cx, cy, cz);
    }
    for (let cx = 0; cx < WORLD_X / CHUNK; cx++) {
      for (let cy = 0; cy < WORLD_Y / CHUNK; cy++) {
        for (let cz = 0; cz < WORLD_Z / CHUNK; cz++) {
          this.buildChunk(cx, cy, cz);
        }
      }
    }
    this.dirty.clear();
  }

  buildChunk(cx, cy, cz) {
    const key = this.chunkKey(cx, cy, cz);
    const old = this.chunks.get(key);
    if (old) {
      this.chunkGroup.remove(old);
      old.geometry.dispose();
      this.chunks.delete(key);
    }
    const positions = [];
    const normals = [];
    const uvs = [];
    const colors = [];
    const indices = [];
    const x0 = cx * CHUNK, y0 = cy * CHUNK, z0 = cz * CHUNK;
    const solid = (x, y, z) => this.isSolid(x, y, z);
    const vox = this.voxels;

    for (let ly = 0; ly < CHUNK; ly++) {
      const wy = y0 + ly;
      if (wy >= WORLD_Y) break;
      for (let lz = 0; lz < CHUNK; lz++) {
        const wz = z0 + lz;
        for (let lx = 0; lx < CHUNK; lx++) {
          const wx = x0 + lx;
          const b = vox[this.idx(wx, wy, wz)];
          if (!b) continue;
          const def = BLOCKS[b];
          if (!def) continue;
          const lightBase = Math.max(this.lightAt(wx, wy, wz), def.glow);
          const tint = 0.93 + hash3(wx, wy, wz) * 0.14;
          for (let f = 0; f < 6; f++) {
            const face = FACES[f];
            const nx = wx + face.n[0], ny = wy + face.n[1], nz = wz + face.n[2];
            if (solid(nx, ny, nz)) continue;
            const tile = def.tiles[f];
            const [u0, v0, u1, v1] = tileUV(tile);
            const base = positions.length / 3;
            const faceShade = f === 3 ? 0.82 : 1;
            for (let k = 0; k < 4; k++) {
              const cu = k === 1 || k === 2 ? 1 : 0;
              const cv = k === 2 || k === 3 ? 1 : 0;
              const px = wx + face.p[0] + face.u[0] * cu + face.v[0] * cv;
              const py = wy + face.p[1] + face.u[1] * cu + face.v[1] * cv;
              const pz = wz + face.p[2] + face.u[2] * cu + face.v[2] * cv;
              positions.push(px, py, pz);
              normals.push(face.n[0], face.n[1], face.n[2]);

              // ambient occlusion
              const su = cu ? 1 : -1;
              const sv = cv ? 1 : -1;
              const sx = nx + face.u[0] * su, sy = ny + face.u[1] * su, sz = nz + face.u[2] * su;
              const tx = nx + face.v[0] * sv, ty = ny + face.v[1] * sv, tz = nz + face.v[2] * sv;
              const ox = sx + face.v[0] * sv, oy = sy + face.v[1] * sv, oz = sz + face.v[2] * sv;
              const s1 = solid(sx, sy, sz) ? 1 : 0;
              const s2 = solid(tx, ty, tz) ? 1 : 0;
              const co = solid(ox, oy, oz) ? 1 : 0;
              const ao = s1 && s2 ? 0 : 3 - (s1 + s2 + co);
              const brightness = lightBase * tint * faceShade * AO_LEVEL[ao];
              colors.push(brightness, brightness, brightness);
              uvs.push(cu ? u1 : u0, cv ? v1 : v0);
            }
            indices.push(base, base + 1, base + 2, base, base + 2, base + 3);
          }
        }
      }
    }

    if (!indices.length) return;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    geo.setIndex(indices);
    geo.computeBoundingSphere();
    const mesh = new THREE.Mesh(geo, this.material);
    mesh.name = 'chunk-' + key;
    mesh.receiveShadow = true;
    mesh.castShadow = false;
    mesh.matrixAutoUpdate = false;
    mesh.updateMatrix();
    this.chunkGroup.add(mesh);
    this.chunks.set(key, mesh);
  }

  // ---------- raycast ----------
  raycast(origin, dir, maxDist = 6) {
    let x = Math.floor(origin.x), y = Math.floor(origin.y), z = Math.floor(origin.z);
    const stepX = dir.x >= 0 ? 1 : -1;
    const stepY = dir.y >= 0 ? 1 : -1;
    const stepZ = dir.z >= 0 ? 1 : -1;
    const tDeltaX = dir.x === 0 ? Infinity : Math.abs(1 / dir.x);
    const tDeltaY = dir.y === 0 ? Infinity : Math.abs(1 / dir.y);
    const tDeltaZ = dir.z === 0 ? Infinity : Math.abs(1 / dir.z);
    let tMaxX = dir.x === 0 ? Infinity : (dir.x > 0 ? (x + 1 - origin.x) : (origin.x - x)) / Math.abs(dir.x);
    let tMaxY = dir.y === 0 ? Infinity : (dir.y > 0 ? (y + 1 - origin.y) : (origin.y - y)) / Math.abs(dir.y);
    let tMaxZ = dir.z === 0 ? Infinity : (dir.z > 0 ? (z + 1 - origin.z) : (origin.z - z)) / Math.abs(dir.z);
    let normal = [0, 1, 0];
    let t = 0;
    for (let i = 0; i < 256; i++) {
      if (this.isSolid(x, y, z)) {
        return { x, y, z, block: this.get(x, y, z), normal, distance: t };
      }
      if (tMaxX < tMaxY && tMaxX < tMaxZ) {
        x += stepX; t = tMaxX; tMaxX += tDeltaX; normal = [-stepX, 0, 0];
      } else if (tMaxY < tMaxZ) {
        y += stepY; t = tMaxY; tMaxY += tDeltaY; normal = [0, -stepY, 0];
      } else {
        z += stepZ; t = tMaxZ; tMaxZ += tDeltaZ; normal = [0, 0, -stepZ];
      }
      if (t > maxDist) break;
    }
    return null;
  }

  // ---------- save ----------
  encode() {
    const vox = this.voxels;
    const runs = [];
    let prev = vox[0], count = 0;
    for (let i = 0; i < vox.length; i++) {
      const v = vox[i];
      if (v === prev && count < 65535) count++;
      else { runs.push(prev, count); prev = v; count = 1; }
    }
    runs.push(prev, count);
    const bytes = new Uint8Array(runs.length * 3);
    for (let i = 0, j = 0; i < runs.length; i += 2, j += 3) {
      bytes[j] = runs[i];
      bytes[j + 1] = runs[i + 1] & 255;
      bytes[j + 2] = (runs[i + 1] >> 8) & 255;
    }
    return base64FromBytes(bytes);
  }

  decode(str) {
    if (!str) return false;
    const bytes = bytesFromBase64(str);
    const out = new Uint8Array(this.voxels.length);
    let p = 0;
    for (let i = 0; i < bytes.length; i += 3) {
      const v = bytes[i];
      const c = bytes[i + 1] | (bytes[i + 2] << 8);
      if (p + c > out.length) return false;
      out.fill(v, p, p + c);
      p += c;
    }
    if (p !== out.length) return false;
    this.voxels = out;
    this.rebuildAll();
    return true;
  }
}

import * as THREE from '../vendor/three.module.js';
import { BLOCK, BLOCKS, SURFACE } from './world.js';

const EYE = 1.62;
const HEIGHT = 1.78;
const RADIUS = 0.31;
const GRAVITY = 26;

export class Player {
  constructor(scene, camera, world) {
    this.scene = scene;
    this.camera = camera;
    this.world = world;
    this.pos = new THREE.Vector3(32.5, world.topAt(32.5, 42.5), 42.5);
    this.vel = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = -0.06;
    this.onGround = false;
    this.keys = new Set();
    this.touchMove = { x: 0, y: 0 };
    this.digHeld = false;
    this.placeQueued = false;
    this.mining = { x: 0, y: 0, z: 0, progress: 0, active: false, block: 0 };
    this.swing = 0;
    this.swingTime = 0;
    this.bobTime = 0;
    this.stepTimer = 0;
    this.shake = 0;
    this.placeCooldown = 0;
    this.warnCooldown = 0;
    this.lampMix = 0;
    this.lampDistance = 12;
    this.enabled = false;
    this.lastBreakSound = 0;
    this.lookSensitivity = 0.0022;

    this.camera.rotation.order = 'YXZ';
    this.scene.add(camera);

    this._buildLights();
    this._buildTool();
    this._buildOutline();
  }

  _buildLights() {
    this.spot = new THREE.SpotLight(0xfff0cf, 0, 26, 0.72, 0.62, 1.35);
    this.spot.position.set(0.15, 0.1, 0);
    this.spot.target.position.set(0, -0.4, -10);
    this.camera.add(this.spot);
    this.camera.add(this.spot.target);

    this.nearLight = new THREE.PointLight(0xffe6b8, 0.7, 9, 1.3);
    this.nearLight.position.set(0, -0.1, -0.3);
    this.camera.add(this.nearLight);
  }

  _buildTool() {
    this.toolGroup = new THREE.Group();
    this.toolGroup.position.set(0.42, -0.4, -0.72);
    this.toolGroup.rotation.set(0.1, -0.25, 0.02);
    this.camera.add(this.toolGroup);

    const wood = new THREE.MeshStandardMaterial({ color: 0x8b5a2b, roughness: 0.8, metalness: 0.05 });
    const metal = new THREE.MeshStandardMaterial({ color: 0xb9c2cc, roughness: 0.35, metalness: 0.75 });
    const dark = new THREE.MeshStandardMaterial({ color: 0x2b2f36, roughness: 0.55, metalness: 0.4 });

    // shovel
    this.shovel = new THREE.Group();
    const handle = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.92, 0.055), wood);
    handle.position.y = 0.08;
    const grip = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.055, 0.075), dark);
    grip.position.y = 0.54;
    const blade = new THREE.Mesh(new THREE.BoxGeometry(0.27, 0.3, 0.05), metal);
    blade.position.set(0, -0.44, 0.005);
    const bladeTip = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.16, 4), metal);
    bladeTip.position.set(0, -0.66, 0.005);
    bladeTip.rotation.set(Math.PI, Math.PI / 4, 0);
    bladeTip.scale.z = 0.35;
    const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 0.09, 8), dark);
    collar.position.y = -0.26;
    this.shovel.add(handle, grip, blade, bladeTip, collar);
    this.shovel.rotation.set(-0.15, 0, 0.08);
    this.toolGroup.add(this.shovel);

    // drill
    this.drill = new THREE.Group();
    this.drill.visible = false;
    const bodyMat = new THREE.MeshStandardMaterial({ color: 0xd18a32, roughness: 0.45, metalness: 0.5 });
    this.drillBodyMat = bodyMat;
    const body = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.115, 0.36, 12), bodyMat);
    body.rotation.x = Math.PI / 2;
    body.position.set(0, 0, -0.02);
    const back = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.09, 0.14, 10), dark);
    back.rotation.x = Math.PI / 2;
    back.position.set(0, 0, 0.2);
    const grip2 = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.22, 0.1), dark);
    grip2.position.set(0, -0.18, 0.08);
    grip2.rotation.x = 0.18;
    this.bitPivot = new THREE.Group();
    this.bitPivot.position.set(0, 0, -0.2);
    const bitMat = new THREE.MeshStandardMaterial({ color: 0xe6eef7, roughness: 0.25, metalness: 0.9 });
    this.bitMat = bitMat;
    const bit = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.3, 10), bitMat);
    bit.rotation.x = -Math.PI / 2;
    bit.position.z = -0.14;
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.105, 0.022, 6, 14), dark);
    ring.position.z = -0.02;
    this.bitPivot.add(bit, ring);
    this.drill.add(body, back, grip2, this.bitPivot);
    this.drill.rotation.set(-0.32, 0.04, 0);
    this.drill.position.set(0, 0.02, 0);
    this.toolGroup.add(this.drill);

    // small light to make the tool readable underground
    const toolLight = new THREE.PointLight(0xffdca8, 0.5, 2.2, 1.5);
    toolLight.position.set(0.2, 0.1, 0.2);
    this.toolGroup.add(toolLight);
  }

  _buildOutline() {
    const geo = new THREE.EdgesGeometry(new THREE.BoxGeometry(1.006, 1.006, 1.006));
    const mat = new THREE.LineBasicMaterial({ color: 0xffc857, transparent: true, opacity: 0.75, depthWrite: false });
    this.outline = new THREE.LineSegments(geo, mat);
    this.outline.visible = false;
    this.outline.renderOrder = 4;
    this.scene.add(this.outline);
  }

  setSpawn(x, y, z, yaw = 0) {
    this.pos.set(x, y, z);
    this.vel.set(0, 0, 0);
    this.yaw = yaw;
    this.pitch = -0.06;
    this.onGround = false;
  }

  teleport(x, y, z) {
    this.pos.set(x, y, z);
    this.vel.set(0, 0, 0);
    this.onGround = false;
  }

  getDepth() {
    return Math.max(0, SURFACE + 1 - this.pos.y);
  }

  look(dx, dy) {
    this.yaw -= dx * this.lookSensitivity;
    this.pitch -= dy * this.lookSensitivity;
    this.pitch = Math.max(-1.48, Math.min(1.48, this.pitch));
  }

  getDir(out = new THREE.Vector3()) {
    const cp = Math.cos(this.pitch);
    out.set(-Math.sin(this.yaw) * cp, Math.sin(this.pitch), -Math.cos(this.yaw) * cp);
    return out;
  }

  collides(px, py, pz) {
    const minX = Math.floor(px - RADIUS), maxX = Math.floor(px + RADIUS);
    const minY = Math.floor(py + 0.002), maxY = Math.floor(py + HEIGHT - 0.002);
    const minZ = Math.floor(pz - RADIUS), maxZ = Math.floor(pz + RADIUS);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          if (this.world.isSolid(x, y, z)) return true;
        }
      }
    }
    return false;
  }

  update(dt, game) {
    if (!this.enabled) {
      this.toolGroup.visible = false;
      this.outline.visible = false;
      this.spot.intensity = 0;
      return;
    }
    this.toolGroup.visible = true;
    this.placeCooldown = Math.max(0, this.placeCooldown - dt);
    this.warnCooldown = Math.max(0, this.warnCooldown - dt);

    // ---- movement input ----
    let f = 0, r = 0;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) f += 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) f -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) r += 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) r -= 1;
    f += -this.touchMove.y;
    r += this.touchMove.x;
    const len = Math.hypot(f, r);
    if (len > 1) { f /= len; r /= len; }
    const sprint = this.keys.has('ShiftLeft') || this.keys.has('ShiftRight');
    const baseSpeed = 4.35 * game.bootsMult * (sprint ? 1.55 : 1);
    const fx = -Math.sin(this.yaw), fz = -Math.cos(this.yaw);
    const rx = Math.cos(this.yaw), rz = -Math.sin(this.yaw);
    const tx = (fx * f + rx * r) * baseSpeed;
    const tz = (fz * f + rz * r) * baseSpeed;
    const accel = this.onGround ? 16 : 5.5;
    this.vel.x += (tx - this.vel.x) * Math.min(1, accel * dt);
    this.vel.z += (tz - this.vel.z) * Math.min(1, accel * dt);

    if ((this.keys.has('Space') || game.jumpQueued) && this.onGround) {
      this.vel.y = 8.4;
      this.onGround = false;
      game.jumpQueued = false;
      game.audio.jump();
    }
    game.jumpQueued = false;

    this.vel.y -= GRAVITY * dt;
    if (this.vel.y < -38) this.vel.y = -38;

    // ---- collision ----
    const wasGround = this.onGround;
    this.onGround = false;
    this.pos.x += this.vel.x * dt;
    if (this.collides(this.pos.x, this.pos.y, this.pos.z)) {
      this.pos.x -= this.vel.x * dt;
      this.vel.x = 0;
    }
    this.pos.z += this.vel.z * dt;
    if (this.collides(this.pos.x, this.pos.y, this.pos.z)) {
      this.pos.z -= this.vel.z * dt;
      this.vel.z = 0;
    }
    this.pos.y += this.vel.y * dt;
    if (this.collides(this.pos.x, this.pos.y, this.pos.z)) {
      this.pos.y -= this.vel.y * dt;
      if (this.vel.y < 0) {
        this.onGround = true;
        if (!wasGround && this.vel.y < -8) game.audio.land();
      }
      this.vel.y = 0;
    }

    // fall out of the world failsafe
    if (this.pos.y < -6) {
      this.teleport(32.5, this.world.topAt(32.5, 42.5), 42.5);
    }

    // ---- camera ----
    const moving = Math.hypot(this.vel.x, this.vel.z) > 0.7 && this.onGround;
    if (moving) {
      this.bobTime += dt * (sprint ? 13 : 9.4);
      this.stepTimer -= dt * (sprint ? 1.5 : 1);
      if (this.stepTimer <= 0) {
        this.stepTimer = 0.46;
        game.audio.step();
      }
    }
    const bob = moving ? Math.sin(this.bobTime) * 0.045 : 0;
    const sway = moving ? Math.cos(this.bobTime * 0.5) * 0.025 : 0;
    this.shake = Math.max(0, this.shake - dt * 2.4);
    const shx = (Math.random() - 0.5) * this.shake * 0.06;
    const shy = (Math.random() - 0.5) * this.shake * 0.06;
    this.camera.position.set(this.pos.x + sway + shx, this.pos.y + EYE + bob + shy, this.pos.z);
    this.camera.rotation.set(this.pitch, this.yaw, 0, 'YXZ');

    // ---- tool ----
    const showDrill = game.power >= 2;
    this.shovel.visible = !showDrill;
    this.drill.visible = showDrill;
    if (showDrill) {
      const colors = [0xd18a32, 0xd18a32, 0xcfd6de, 0x8ff0ff];
      this.drillBodyMat.color.setHex(colors[Math.min(3, game.power - 1)]);
      this.bitMat.color.setHex(game.power >= 3 ? 0xa9f7ff : 0xe6eef7);
    }
    this.toolGroup.position.set(0.42, -0.4 + bob * 0.6, -0.72);
    this.toolGroup.rotation.z = 0.02 + sway * 0.4;
    const miningSwing = this.mining.active ? Math.sin(this.swingTime * 17) : 0;
    if (showDrill) {
      this.toolGroup.position.y += Math.abs(miningSwing) * 0.03;
      this.toolGroup.position.z = -0.72 + (this.mining.active ? 0.05 : 0);
      this.bitPivot.rotation.z += dt * (this.mining.active ? 34 : 3);
    } else {
      this.toolGroup.rotation.x = 0.1 + miningSwing * 0.24;
      this.toolGroup.rotation.y = -0.25 - miningSwing * 0.12;
      this.toolGroup.position.y += miningSwing * 0.02;
    }

    // ---- lamp ----
    const depth = this.getDepth();
    const targetMix = Math.max(0, Math.min(1, (depth - 2) / 7));
    this.lampMix += (targetMix - this.lampMix) * Math.min(1, dt * 3);
    this.lampDistance += (game.lampDistance - this.lampDistance) * Math.min(1, dt * 3);
    this.spot.distance = this.lampDistance + 6;
    this.spot.intensity = this.lampMix * 190 + 4;
    this.spot.angle = 0.74;
    this.nearLight.intensity = 0.55 + this.lampMix * 7.5;
    this.nearLight.distance = 6 + this.lampMix * 8;

    // ---- mining ----
    this.updateMining(dt, game);
  }

  updateMining(dt, game) {
    this.placeCooldown = Math.max(0, this.placeCooldown - dt);
    const camPos = this.camera.position;
    const dir = this.getDir(new THREE.Vector3());
    const hit = this.world.raycast(camPos, dir, 5.6);

    if (hit) {
      this.outline.visible = true;
      this.outline.position.set(hit.x + 0.5, hit.y + 0.5, hit.z + 0.5);
      const isCore = hit.block === BLOCK.CORE;
      this.outline.material.color.setHex(isCore ? 0xffd76a : 0xffc857);
    } else {
      this.outline.visible = false;
    }

    if (!this.digHeld || !hit) {
      this.mining.active = false;
      this.mining.progress = 0;
      this.swingTime = 0;
      if (this.placeQueued && hit && this.placeCooldown <= 0) {
        game.tryPlace(hit);
        this.placeCooldown = 0.22;
      }
      this.placeQueued = false;
      return;
    }
    this.placeQueued = false;

    const def = BLOCKS[hit.block];
    if (!def) return;
    if (game.power < def.power) {
      this.mining.active = false;
      this.mining.progress = 0;
      if (this.warnCooldown <= 0) {
        game.warn(`Your drill is too weak for ${def.name}. Upgrade it at the Ore-O-Matic.`, 'bad');
        this.warnCooldown = 1.4;
        game.audio.clank();
      }
      return;
    }
    if (!game.canCollect(hit.block)) {
      this.mining.active = false;
      this.mining.progress = 0;
      if (this.warnCooldown <= 0) {
        game.warn('Backpack full! Winch up and sell your haul.', 'bad');
        this.warnCooldown = 1.4;
        game.audio.clank();
      }
      return;
    }

    if (!this.mining.active || this.mining.x !== hit.x || this.mining.y !== hit.y || this.mining.z !== hit.z) {
      this.mining.x = hit.x;
      this.mining.y = hit.y;
      this.mining.z = hit.z;
      this.mining.progress = 0;
      this.mining.active = true;
      this.mining.block = hit.block;
    }
    this.swingTime += dt;
    this.mining.progress += (dt * game.speedMult) / def.hardness;
    this.shake = Math.max(this.shake, 0.25);
    game.audio.digLoop(dt);
    if (Math.random() < dt * 12) game.particles.mine(hit.x + 0.5, hit.y + 0.5, hit.z + 0.5, hit.block, 1);

    if (this.mining.progress >= 1) {
      const ok = game.breakBlock(hit.x, hit.y, hit.z, hit.block);
      this.mining.progress = 0;
      this.mining.active = false;
      this.swingTime = 0;
      if (ok) this.shake = 0.55;
    }
  }

  applyUpgrades(game) {
    // visual/readability hooks; stats are read from game each frame
    this.lampDistance = game.lampDistance;
  }
}

import * as THREE from '../vendor/three.module.js';
import { BLOCKS } from './world.js';

const MAX = 220;

export class Particles {
  constructor(scene) {
    this.scene = scene;
    const geo = new THREE.BoxGeometry(0.16, 0.16, 0.16);
    const mat = new THREE.MeshLambertMaterial({ color: 0xffffff });
    this.mesh = new THREE.InstancedMesh(geo, mat, MAX);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.castShadow = false;
    this.mesh.receiveShadow = false;
    scene.add(this.mesh);

    this.items = [];
    for (let i = 0; i < MAX; i++) {
      this.items.push({ life: 0, maxLife: 1, pos: new THREE.Vector3(), vel: new THREE.Vector3(), scale: 1, rot: new THREE.Euler(), spin: new THREE.Vector3() });
    }
    this.cursor = 0;
    this.dummy = new THREE.Object3D();
    this.color = new THREE.Color();
    for (let i = 0; i < MAX; i++) {
      this.dummy.scale.setScalar(0);
      this.dummy.updateMatrix();
      this.mesh.setMatrixAt(i, this.dummy.matrix);
      this.mesh.setColorAt(i, this.color.setHex(0xffffff));
    }
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  spawn(x, y, z, color, count, power = 1) {
    for (let i = 0; i < count; i++) {
      const idx = this.cursor;
      this.cursor = (this.cursor + 1) % MAX;
      const p = this.items[idx];
      p.life = 0.55 + Math.random() * 0.65;
      p.maxLife = p.life;
      p.pos.set(x + (Math.random() - 0.5) * 0.7, y + (Math.random() - 0.5) * 0.7, z + (Math.random() - 0.5) * 0.7);
      const a = Math.random() * Math.PI * 2;
      const sp = (1.1 + Math.random() * 2.4) * power;
      p.vel.set(Math.cos(a) * sp * 0.7, 1.5 + Math.random() * 2.6 * power, Math.sin(a) * sp * 0.7);
      p.scale = 0.5 + Math.random() * 0.9;
      p.rot.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
      p.spin.set((Math.random() - 0.5) * 8, (Math.random() - 0.5) * 8, (Math.random() - 0.5) * 8);
      this.color.set(color);
      this.color.offsetHSL(0, 0, (Math.random() - 0.5) * 0.12);
      this.mesh.setColorAt(idx, this.color);
    }
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  mine(x, y, z, blockId, count) {
    const def = BLOCKS[blockId];
    const color = def ? def.color : '#8a5a34';
    this.spawn(x, y, z, color, count, def && def.kind === 'ore' ? 1.35 : 1);
  }

  burst(x, y, z, blockId) {
    this.mine(x, y, z, blockId, 14);
  }

  update(dt) {
    const d = this.dummy;
    let changed = false;
    for (let i = 0; i < MAX; i++) {
      const p = this.items[i];
      if (p.life > 0) {
        p.life -= dt;
        p.vel.y -= 19 * dt;
        p.pos.addScaledVector(p.vel, dt);
        p.rot.x += p.spin.x * dt;
        p.rot.y += p.spin.y * dt;
        p.rot.z += p.spin.z * dt;
        const t = Math.max(0, p.life / p.maxLife);
        const s = p.scale * (0.35 + t * 0.85);
        d.position.copy(p.pos);
        d.rotation.copy(p.rot);
        d.scale.setScalar(s);
        d.updateMatrix();
        this.mesh.setMatrixAt(i, d.matrix);
        changed = true;
      } else if (p.life > -1) {
        p.life = -2;
        d.position.set(0, -50, 0);
        d.scale.setScalar(0);
        d.updateMatrix();
        this.mesh.setMatrixAt(i, d.matrix);
        changed = true;
      }
    }
    if (changed) this.mesh.instanceMatrix.needsUpdate = true;
  }
}

export class GameAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.lastDig = 0;
    this.lastStep = 0;
    this.ambientGain = null;
    this.ambientFilter = null;
    this.rumbleGain = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.master.connect(this.ctx.destination);

    // noise buffer
    const len = Math.floor(this.ctx.sampleRate * 2);
    this.noise = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = this.noise.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2;
    }

    // ambient wind
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    this.ambientFilter = this.ctx.createBiquadFilter();
    this.ambientFilter.type = 'lowpass';
    this.ambientFilter.frequency.value = 420;
    this.ambientGain = this.ctx.createGain();
    this.ambientGain.gain.value = 0.055;
    src.connect(this.ambientFilter);
    this.ambientFilter.connect(this.ambientGain);
    this.ambientGain.connect(this.master);
    src.start();

    // underground rumble
    const osc = this.ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = 41;
    this.rumbleGain = this.ctx.createGain();
    this.rumbleGain.gain.value = 0;
    const rumbleFilter = this.ctx.createBiquadFilter();
    rumbleFilter.type = 'lowpass';
    rumbleFilter.frequency.value = 90;
    osc.connect(rumbleFilter);
    rumbleFilter.connect(this.rumbleGain);
    this.rumbleGain.connect(this.master);
    osc.start();
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.05);
  }

  setDepth(depth) {
    if (!this.ctx) return;
    const t = Math.max(0, Math.min(1, (depth - 2) / 30));
    this.ambientFilter.frequency.setTargetAtTime(420 - t * 280, this.ctx.currentTime, 0.4);
    this.ambientGain.gain.setTargetAtTime(0.055 - t * 0.03, this.ctx.currentTime, 0.4);
    this.rumbleGain.gain.setTargetAtTime(t * 0.045, this.ctx.currentTime, 0.5);
  }

  _env(node, gain, attack, decay, time = 0) {
    const t = this.ctx.currentTime + time;
    node.gain.setValueAtTime(0.0001, t);
    node.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + attack);
    node.gain.exponentialRampToValueAtTime(0.0001, t + attack + decay);
  }

  _noise(duration, filterType, freq, q, gain, time = 0) {
    if (!this.ctx) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const g = this.ctx.createGain();
    const t = this.ctx.currentTime + time;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    src.connect(filter); filter.connect(g); g.connect(this.master);
    src.start(t);
    src.stop(t + duration + 0.02);
  }

  _tone(freq, duration, type, gain, slideTo = null, time = 0) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + time;
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(slideTo, t + duration);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    osc.connect(g); g.connect(this.master);
    osc.start(t); osc.stop(t + duration + 0.03);
  }

  digLoop() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    if (now - this.lastDig < 0.13) return;
    this.lastDig = now;
    this._noise(0.09, 'bandpass', 900 + Math.random() * 900, 1.2, 0.06);
    this._tone(120 + Math.random() * 50, 0.07, 'triangle', 0.035);
  }

  breakBlock() {
    this._noise(0.2, 'lowpass', 780, 0.8, 0.12);
    this._tone(95, 0.16, 'sine', 0.09, 55);
  }

  pickup() {
    this._tone(660, 0.07, 'sine', 0.045, 990);
  }

  cash() {
    [523, 659, 784, 1046].forEach((f, i) => this._tone(f, 0.16, 'triangle', 0.06, null, i * 0.07));
  }

  buy() {
    this._tone(392, 0.1, 'triangle', 0.07, 523);
    this._tone(523, 0.16, 'triangle', 0.06, 784, 0.08);
  }

  clank() {
    this._noise(0.1, 'highpass', 1400, 1.4, 0.05);
    this._tone(150, 0.1, 'square', 0.035, 90);
  }

  jump() { this._tone(240, 0.11, 'sine', 0.04, 430); }
  land() { this._noise(0.12, 'lowpass', 360, 0.9, 0.08); }

  step() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    if (now - this.lastStep < 0.12) return;
    this.lastStep = now;
    this._noise(0.07, 'bandpass', 300 + Math.random() * 200, 1.6, 0.025);
  }

  winch() {
    this._noise(0.6, 'bandpass', 700, 0.7, 0.05);
    this._tone(220, 0.5, 'sine', 0.05, 700);
  }

  win() {
    [392, 523, 659, 784, 1046].forEach((f, i) => this._tone(f, 0.7, 'triangle', 0.08, null, i * 0.12));
    this._noise(1.4, 'lowpass', 500, 0.6, 0.06);
  }
}

import * as THREE from '../vendor/three.module.js';
import { SURFACE, WORLD_X, WORLD_Z } from './world.js';
import { makeCanvasTexture, makeSignTexture } from './textures.js';

const CENTER = WORLD_X / 2;
const TOP = SURFACE + 1;

function mat(color, roughness = 0.85, metalness = 0.02) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness });
}

function box(w, h, d, material, x = 0, y = 0, z = 0, cast = true, receive = true) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  m.position.set(x, y, z);
  m.castShadow = cast;
  m.receiveShadow = receive;
  return m;
}

function radialTexture(inner, outer) {
  return makeCanvasTexture(128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, inner);
    g.addColorStop(0.35, inner);
    g.addColorStop(1, outer);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

export class Environment {
  constructor(scene, world) {
    this.scene = scene;
    this.world = world;
    this.time = 0;
    this.interactables = [];
    this.clouds = [];
    this.coreGlow = null;
    this.holo = null;
    this.dust = null;
    this.dustMat = null;

    this._lights();
    this._sky();
    this._ground();
    this._hills();
    this._fence();
    this._trees();
    this._shed();
    this._machines();
    this._props();
    this._grassAndFlowers();
    this._coreGlow();
    this._dust();

    this.skyFog = new THREE.Color(0xc7dfea);
    this.caveFog = new THREE.Color(0x07070c);
    scene.fog = new THREE.Fog(0xc7dfea, 65, 260);
    scene.background = new THREE.Color(0xc7dfea);
  }

  _lights() {
    this.hemi = new THREE.HemisphereLight(0xbfe4ff, 0x6d5636, 1.35);
    this.scene.add(this.hemi);

    this.sun = new THREE.DirectionalLight(0xfff1d0, 2.6);
    this.sun.position.set(CENTER + 48, TOP + 72, CENTER + 34);
    this.sun.target.position.set(CENTER, TOP, CENTER);
    this.sun.castShadow = true;
    this.sun.shadow.mapSize.set(2048, 2048);
    this.sun.shadow.camera.left = -46;
    this.sun.shadow.camera.right = 46;
    this.sun.shadow.camera.top = 46;
    this.sun.shadow.camera.bottom = -46;
    this.sun.shadow.camera.near = 1;
    this.sun.shadow.camera.far = 180;
    this.sun.shadow.bias = -0.0006;
    this.sun.shadow.normalBias = 0.03;
    this.scene.add(this.sun);
    this.scene.add(this.sun.target);

    this.fill = new THREE.DirectionalLight(0xffd9a8, 0.35);
    this.fill.position.set(CENTER - 30, TOP + 20, CENTER - 40);
    this.scene.add(this.fill);
  }

  _sky() {
    const geo = new THREE.SphereGeometry(460, 32, 20);
    const material = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        top: { value: new THREE.Color('#5fa8dc') },
        mid: { value: new THREE.Color('#a9d6ee') },
        horizon: { value: new THREE.Color('#ffe0b0') },
        sunDir: { value: new THREE.Vector3(0.42, 0.66, 0.32).normalize() },
        sunColor: { value: new THREE.Color('#fff2c4') },
      },
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = position;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying vec3 vDir;
        uniform vec3 top;
        uniform vec3 mid;
        uniform vec3 horizon;
        uniform vec3 sunDir;
        uniform vec3 sunColor;
        void main() {
          vec3 d = normalize(vDir);
          float h = clamp(d.y, -1.0, 1.0);
          vec3 col = mix(horizon, mid, smoothstep(0.0, 0.22, h));
          col = mix(col, top, smoothstep(0.18, 0.72, h));
          float sd = max(dot(d, sunDir), 0.0);
          col += sunColor * pow(sd, 320.0) * 1.4;
          col += sunColor * pow(sd, 12.0) * 0.10;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    this.skyMesh = new THREE.Mesh(geo, material);
    this.skyMesh.renderOrder = -10;
    this.skyMesh.frustumCulled = false;
    this.scene.add(this.skyMesh);

    const sunTex = radialTexture('rgba(255,248,214,1)', 'rgba(255,220,140,0)');
    const sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: sunTex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending }));
    sunSprite.position.set(0.42, 0.66, 0.32).normalize().multiplyScalar(430);
    sunSprite.scale.set(90, 90, 1);
    this.scene.add(sunSprite);

    // clouds
    const cloudMat = new THREE.MeshLambertMaterial({ color: 0xfffbf2, transparent: true, opacity: 0.92, fog: false });
    for (let i = 0; i < 14; i++) {
      const g = new THREE.Group();
      const n = 3 + Math.floor(Math.random() * 3);
      for (let j = 0; j < n; j++) {
        const puff = new THREE.Mesh(new THREE.IcosahedronGeometry(3 + Math.random() * 3.4, 0), cloudMat);
        puff.position.set((Math.random() - 0.5) * 12, (Math.random() - 0.5) * 2.4, (Math.random() - 0.5) * 6);
        puff.scale.y = 0.55;
        g.add(puff);
      }
      g.position.set(CENTER + (Math.random() - 0.5) * 300, TOP + 60 + Math.random() * 45, CENTER + (Math.random() - 0.5) * 300);
      g.userData.speed = 0.6 + Math.random() * 0.9;
      this.clouds.push(g);
      this.scene.add(g);
    }
  }

  _ground() {
    const grassTex = makeCanvasTexture(128, 128, (ctx, w, h) => {
      ctx.fillStyle = '#6f9f45';
      ctx.fillRect(0, 0, w, h);
      for (let i = 0; i < 2600; i++) {
        ctx.fillStyle = ['#669741', '#7aab4e', '#5f8f3a', '#84b558'][(Math.random() * 4) | 0];
        ctx.fillRect(Math.random() * w, Math.random() * h, 2, 2);
      }
    });
