96:         horizon: { value: new THREE.Color('#ffe0b0') },
97:         sunDir: { value: new THREE.Vector3(0.42, 0.66, 0.32).normalize() },
98:         sunColor: { value: new THREE.Color('#fff2c4') },
99:       },
100:       vertexShader: `
101:         varying vec3 vDir;
102:         void main() {
103:           vDir = position;
104:           gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
105:         }
106:       `,
107:       fragmentShader: `
108:         varying vec3 vDir;
109:         uniform vec3 top;
110:         uniform vec3 mid;
111:         uniform vec3 horizon;
112:         uniform vec3 sunDir;
113:         uniform vec3 sunColor;
114:         void main() {
115:           vec3 d = normalize(vDir);
116:           float h = clamp(d.y, -1.0, 1.0);
117:           vec3 col = mix(horizon, mid, smoothstep(0.0, 0.22, h));
118:           col = mix(col, top, smoothstep(0.18, 0.72, h));
119:           float sd = max(dot(d, sunDir), 0.0);
120:           col += sunColor * pow(sd, 320.0) * 1.4;
121:           col += sunColor * pow(sd, 12.0) * 0.10;
122:           gl_FragColor = vec4(col, 1.0);
123:         }
124:       `,
125:     });
126:     this.skyMesh = new THREE.Mesh(geo, material);
