195:   _fence() {
196:     const wood = mat(0x6b4a2c, 0.9);
197:     const woodDark = mat(0x563a22, 0.9);
198:     const half = 24;
199:     const step = 2.4;
200:     const posts = [];
201:     const rails = [];
202:     const addPost = (x, z) => posts.push({ x, z });
203:     for (let x = CENTER - half; x <= CENTER + half + 0.01; x += step) {
204:       addPost(x, CENTER - half);
205:       addPost(x, CENTER + half);
206:     }
207:     for (let z = CENTER - half + step; z <= CENTER + half - step + 0.01; z += step) {
208:       addPost(CENTER - half, z);
209:       addPost(CENTER + half, z);
210:     }
211:     // gate gap on the south fence (z = CENTER + half)
212:     const gateMin = CENTER - 2.5, gateMax = CENTER + 2.5;
213: 
214:     const postGeo = new THREE.BoxGeometry(0.22, 1.35, 0.22);
215:     const postMesh = new THREE.InstancedMesh(postGeo, wood, posts.length);
216:     const dummy = new THREE.Object3D();
217:     let pi = 0;
218:     for (const p of posts) {
219:       if (p.z === CENTER + half && p.x > gateMin && p.x < gateMax) continue;
220:       const y = this.world.topAt(p.x, p.z);
221:       dummy.position.set(p.x, y + 0.55, p.z);
222:       dummy.rotation.set(0, 0, 0);
223:       dummy.updateMatrix();
224:       postMesh.setMatrixAt(pi++, dummy.matrix);
225:     }
226:     postMesh.count = pi;
227:     postMesh.castShadow = true;
228:     postMesh.receiveShadow = true;
229:     this.scene.add(postMesh);
230: 
231:     const railGeo = new THREE.BoxGeometry(step, 0.13, 0.09);
232:     const railMesh = new THREE.InstancedMesh(railGeo, woodDark, 220);
233:     let ri = 0;
234:     const addRail = (x, z, rotY, h) => {
235:       const y = this.world.topAt(x, z);
236:       dummy.position.set(x, y + h, z);
237:       dummy.rotation.set(0, rotY, 0);
238:       dummy.updateMatrix();
239:       railMesh.setMatrixAt(ri++, dummy.matrix);
240:     };
241:     for (let x = CENTER - half + step / 2; x < CENTER + half; x += step) {
242:       addRail(x, CENTER - half, 0, 0.45);
243:       addRail(x, CENTER - half, 0, 1.02);
244:       if (!(x + step / 2 > gateMin && x - step / 2 < gateMax)) {
245:         addRail(x, CENTER + half, 0, 0.45);
246:         addRail(x, CENTER + half, 0, 1.02);
247:       }
248:     }
249:     for (let z = CENTER - half + step / 2; z < CENTER + half; z += step) {
250:       addRail(CENTER - half, z, Math.PI / 2, 0.45);
251:       addRail(CENTER - half, z, Math.PI / 2, 1.02);
252:       addRail(CENTER + half, z, Math.PI / 2, 0.45);
253:       addRail(CENTER + half, z, Math.PI / 2, 1.02);
254:     }
255:     railMesh.count = ri;
256:     railMesh.castShadow = true;
257:     railMesh.receiveShadow = true;
258:     this.scene.add(railMesh);
259: 
260:     // gate posts and a little arch
261:     for (const x of [gateMin, gateMax]) {
262:       const y = this.world.topAt(x, CENTER + half);
263:       const post = box(0.3, 2.1, 0.3, wood, x, y + 0.9, CENTER + half);
264:       this.scene.add(post);
265:     }
266:     const arch = box(gateMax - gateMin + 0.6, 0.22, 0.22, woodDark, CENTER, this.world.topAt(CENTER, CENTER + half) + 1.95, CENTER + half);
267:     this.scene.add(arch);
268:   }
