239:         if (this.mode === 'playing' && !this.pointerLocked) { e.preventDefault(); this.pauseGame(); return; }
240:         return;
241:       }
242:       if (this.mode !== 'playing') return;
243:       if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space', 'ShiftLeft', 'ShiftRight'].includes(code)) {
244:         e.preventDefault();
245:         this.player.keys.add(code);
246:       }
247:       if (code === 'KeyF') { e.preventDefault(); this.winch(); }
248:       if (code === 'KeyE') { e.preventDefault(); this.interact(); }
249:       if (code === 'KeyM') { this.toggleMute(); }
250:       if (code === 'KeyH') { this.pauseGame(); }
251:     });
252:     window.addEventListener('keyup', (e) => {
253:       if (!this.player) return;
254:       this.player.keys.delete(e.code);
255:     });
256:     window.addEventListener('blur', () => {
257:       if (this.player) {
258:         this.player.keys.clear();
259:         this.player.digHeld = false;
260:       }
261:     });
262: 
263:     document.addEventListener('visibilitychange', () => {
264:       if (document.hidden && this.mode === 'playing') this.pauseGame();
265:       if (document.hidden) this.saveGame();
266:     });
267:     window.addEventListener('pagehide', () => this.saveGame());
268: 
269:     this._bindTouch();
270:   }
