272:   _bindTouch() {
273:     const joy = this.ui.el.joystick;
274:     const knob = this.ui.el.joystickKnob;
275:     const updateJoy = (e) => {
276:       const r = joy.getBoundingClientRect();
277:       let dx = e.clientX - (r.left + r.width / 2);
278:       let dy = e.clientY - (r.top + r.height / 2);
279:       const max = 42;
280:       const d = Math.hypot(dx, dy);
281:       if (d > max) { dx = (dx / d) * max; dy = (dy / d) * max; }
282:       knob.style.transform = `translate(${dx}px, ${dy}px)`;
283:       if (this.player) {
284:         this.player.touchMove.x = dx / max;
285:         this.player.touchMove.y = dy / max;
286:       }
287:     };
288:     joy.addEventListener('pointerdown', (e) => {
289:       e.preventDefault();
290:       this.joyPointer = e.pointerId;
291:       try { joy.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
292:       updateJoy(e);
293:     });
294:     joy.addEventListener('pointermove', (e) => {
295:       if (e.pointerId === this.joyPointer) updateJoy(e);
296:     });
297:     const endJoy = (e) => {
298:       if (e.pointerId !== this.joyPointer) return;
299:       this.joyPointer = null;
300:       knob.style.transform = 'translate(0px, 0px)';
301:       if (this.player) this.player.touchMove.x = this.player.touchMove.y = 0;
302:     };
303:     joy.addEventListener('pointerup', endJoy);
304:     joy.addEventListener('pointercancel', endJoy);
305: 
306:     const dig = this.ui.el.btnDig;
307:     dig.addEventListener('pointerdown', (e) => {
308:       e.preventDefault();
309:       if (this.player) this.player.digHeld = true;
310:     });
311:     const stopDig = (e) => {
312:       e.preventDefault();
313:       if (this.player) this.player.digHeld = false;
314:     };
315:     dig.addEventListener('pointerup', stopDig);
316:     dig.addEventListener('pointercancel', stopDig);
317:     dig.addEventListener('pointerleave', stopDig);
318: 
319:     this.ui.el.btnJump.addEventListener('pointerdown', (e) => { e.preventDefault(); this.jumpQueued = true; });
320:     this.ui.el.btnRecall.addEventListener('pointerdown', (e) => { e.preventDefault(); this.winch(); });
321:     this.ui.el.btnInteract.addEventListener('pointerdown', (e) => { e.preventDefault(); this.interact(); });
322: 
323:     this.canvas.addEventListener('pointerdown', (e) => {
324:       if (e.pointerType !== 'touch' || this.mode !== 'playing') return;
325:       this.lookPointer = e.pointerId;
326:       this.lookLast = { x: e.clientX, y: e.clientY };
327:     });
328:     this.canvas.addEventListener('pointermove', (e) => {
329:       if (e.pointerType !== 'touch' || this.lookPointer !== e.pointerId) return;
330:       const dx = e.clientX - this.lookLast.x;
331:       const dy = e.clientY - this.lookLast.y;
332:       this.lookLast = { x: e.clientX, y: e.clientY };
333:       this.player.look(dx * 1.55, dy * 1.55);
334:     });
335:     const endLook = (e) => {
336:       if (this.lookPointer === e.pointerId) this.lookPointer = null;
337:     };
338:     this.canvas.addEventListener('pointerup', endLook);
339:     this.canvas.addEventListener('pointercancel', endLook);
340:   }
