480:   // ---------- gameplay ----------
481:   get state() { return this.data; }
482:   get speedMult() { return [1, 1.6, 2.3, 3.3, 4.8][this.data.upgrades.speed || 0]; }
483:   get power() { return 1 + (this.data.upgrades.power || 0); }
484:   get capacity() { return [30, 50, 75, 110, 160][this.data.upgrades.pack || 0]; }
485:   get bootsMult() { return [1, 1.14, 1.28, 1.45][this.data.upgrades.boots || 0]; }
486:   get lampDistance() { return [12, 18, 26, 36][this.data.upgrades.lamp || 0]; }
487:   get upgradeDefs() { return UPGRADES; }
488: 
489:   getCapacity() { return this.capacity; }
490: 
491:   getWeight() {
492:     let w = 0;
493:     for (const id in this.data.inventory) {
494:       const def = BLOCKS[id];
495:       if (def) w += def.weight * this.data.inventory[id];
496:     }
497:     return w;
498:   }
499: 
500:   canCollect(blockId) {
501:     if (blockId === BLOCK.CORE) return true;
502:     const def = BLOCKS[blockId];
503:     if (!def) return false;
504:     return this.getWeight() + def.weight <= this.capacity + 0.0001;
505:   }
506: 
507:   getInventoryValue() {
508:     let v = 0;
509:     for (const id in this.data.inventory) {
510:       const def = BLOCKS[id];
511:       if (def) v += def.value * this.data.inventory[id];
512:     }
513:     return Math.round(v);
514:   }
515: 
516:   breakBlock(x, y, z, blockId) {
517:     if (!this.canCollect(blockId)) {
518:       this.warn('Backpack full! Winch up and sell your haul.', 'bad');
519:       return false;
520:     }
521:     const def = BLOCKS[blockId];
522:     this.world.set(x, y, z, BLOCK.AIR);
523:     this.world.flushDirty();
524:     this.data.inventory[blockId] = (this.data.inventory[blockId] || 0) + 1;
525:     this.data.mined++;
526:     this.needSave = true;
527:     this.particles.burst(x + 0.5, y + 0.5, z + 0.5, blockId);
528:     this.audio.breakBlock();
529:     this.audio.pickup();
530:     if (def && def.kind === 'ore') {
531:       this.ui.toast(def.name + ' collected', 'good', '+' + def.name.toUpperCase());
532:     }
533:     if (blockId === BLOCK.CORE) {
534:       this.triggerWin();
535:     }
536:     this.ui.updateHUD(this);
537:     return true;
538:   }
