540:   tryPlace(hit) {
541:     if (!hit) return;
542:     const n = hit.normal;
543:     const x = hit.x + n[0], y = hit.y + n[1], z = hit.z + n[2];
544:     if (x < 0 || x >= WORLD_X || z < 0 || z >= WORLD_Z || y < 0 || y >= WORLD_Y) return;
545:     if (this.world.isSolid(x, y, z)) return;
546:     if (!(this.data.inventory[BLOCK.DIRT] > 0)) {
547:       if (this.player.warnCooldown <= 0) {
548:         this.warn('No dirt in your backpack. Dig some first.', 'bad');
549:         this.player.warnCooldown = 1.2;
550:       }
551:       return;
552:     }
553:     // don't entomb yourself
554:     const r = 0.32, h = 1.78;
555:     const p = this.player.pos;
556:     if (x + 1 > p.x - r && x < p.x + r && y + 1 > p.y && y < p.y + h && z + 1 > p.z - r && z < p.z + r) {
557:       this.warn('Not inside your own head, please.', 'bad');
558:       return;
559:     }
560:     this.world.set(x, y, z, BLOCK.DIRT);
561:     this.world.flushDirty();
562:     this.data.inventory[BLOCK.DIRT]--;
563:     if (this.data.inventory[BLOCK.DIRT] <= 0) delete this.data.inventory[BLOCK.DIRT];
564:     this.needSave = true;
565:     this.particles.mine(x + 0.5, y + 0.5, z + 0.5, BLOCK.DIRT, 4);
566:     this.audio.breakBlock();
567:     this.ui.updateHUD(this);
568:   }
