570:   getInteractable() {
571:     if (!this.env || !this.player) return null;
572:     let best = null;
573:     let bestD = Infinity;
574:     for (const item of this.env.interactables) {
575:       const d = this.player.pos.distanceTo(item.position);
576:       if (d < item.radius && d < bestD) { best = item; bestD = d; }
577:     }
578:     return best;
579:   }
