625:   buyUpgrade(id) {
626:     const def = UPGRADES.find((u) => u.id === id);
627:     if (!def) return;
628:     const level = this.data.upgrades[id] || 0;
629:     if (level >= def.levels.length) return;
630:     const cost = def.levels[level].cost;
631:     if (this.data.money < cost) return;
632:     this.data.money -= cost;
633:     this.data.upgrades[id] = level + 1;
634:     this.needSave = true;
635:     this.audio.buy();
636:     const label = def.name + ' upgraded';
637:     this.ui.toast(label, 'good', 'LEVEL ' + (level + 1));
638:     if (id === 'power' && level + 1 >= 1) {
639:       this.ui.toast('Steel drill online. Deepstone and iron are no match.', 'good');
640:     }
641:     this.ui.refreshShop();
642:     this.ui.updateHUD(this);
643:     this.saveGame();
644:   }
