650:   winch() {
651:     if (this.mode !== 'playing' || this.winching) return;
652:     const depth = this.player.getDepth();
653:     const spawn = this.surfaceSpawn();
654:     let target = null;
655:     let up = false;
656:     if (depth > 1.5) {
657:       target = spawn;
658:       up = true;
659:     } else if (this.data.checkpoint) {
660:       const c = this.data.checkpoint;
661:       target = this.safeSpotNear(c.x, c.y, c.z);
662:       if (!target) {
663:         this.warn('The winch rope is blocked. Dig out a little room.', 'bad');
664:         return;
665:       }
666:     } else {
667:       this.warn('Dig a little deeper first. The winch needs somewhere to go.', 'bad');
668:       return;
669:     }
670:     this.winching = true;
671:     this.player.digHeld = false;
672:     this.ui.fade(true);
673:     this.audio.winch();
674:     setTimeout(() => {
675:       this.player.teleport(target.x, target.y, target.z);
676:       this.player.vel.set(0, 0, 0);
677:       if (up) this.player.yaw = 0;
678:       this.player.keys.clear();
679:       this.ui.fade(false);
680:       this.winching = false;
681:       this.needSave = true;
682:       this.ui.updateHUD(this);
683:     }, 280);
684:   }
685: 
686:   safeSpotNear(x, y, z) {
687:     for (let dy = 0; dy <= 8; dy++) {
688:       for (const ox of [0, 0.6, -0.6, 1.2, -1.2]) {
689:         for (const oz of [0, 0.6, -0.6, 1.2, -1.2]) {
690:           const px = x + ox, py = y + dy, pz = z + oz;
691:           if (this.isSafe(px, py, pz)) return { x: px, y: py, z: pz };
692:         }
693:       }
694:     }
695:     return null;
696:   }
697: 
698:   getObjective() {
699:     if (this.data.won) return { text: 'Keep digging. The hole is yours.', reward: 0 };
700:     const next = GOALS.find((g) => !this.data.milestones.includes(g.d));
701:     if (next) return { text: 'Dig down ' + next.d + ' metres', reward: next.reward };
702:     return { text: 'Find the Heart of the Hole', reward: 0 };
703:   }
704: 
705:   checkMilestones() {
706:     const depth = this.data.maxDepth;
707:     for (const g of GOALS) {
708:       if (depth >= g.d && !this.data.milestones.includes(g.d)) {
709:         this.data.milestones.push(g.d);
710:         this.data.money += g.reward;
711:         this.data.earned += g.reward;
712:         this.needSave = true;
713:         this.audio.cash();
714:         this.ui.toast(g.label, 'good', '+$' + g.reward);
715:         this.ui.popObjective();
716:       }
717:     }
718:   }
719: 
720:   triggerWin() {
721:     if (this.data.won) return;
722:     this.data.won = true;
723:     this.mode = 'won';
724:     this.player.enabled = false;
725:     this.player.digHeld = false;
726:     if (document.pointerLockElement) document.exitPointerLock();
727:     this.audio.win();
728:     this.ui.showWin({
729:       depth: this.data.maxDepth,
730:       mined: this.data.mined,
731:       earned: this.data.earned,
732:       time: formatTime(this.data.time),
733:     });
734:     this.saveGame();
735:   }
736: 
737:   // ---------- frame ----------
738:   loop() {
739:     requestAnimationFrame(() => this.loop());
740:     const dt = Math.min(this.clock.getDelta(), 0.05);
741: 
742:     if (this.mode === 'menu') {
743:       this.menuT += dt * 0.075;
744:       const sway = Math.sin(this.menuT * 0.7) * 2.2;
745:       this.camera.position.set(CENTER + sway, SURFACE + 3.0 + Math.sin(this.menuT * 1.3) * 0.18, SPAWN_Z);
746:       this.camera.lookAt(CENTER, SURFACE - 0.6, CENTER);
747:       this.env.update(dt, this.camera.position, 0);
748:       this.particles.update(dt);
749:     } else if (this.mode === 'playing') {
750:       this.data.time += dt;
751:       this.player.update(dt, this);
752:       const depth = this.player.getDepth();
753:       if (depth > this.data.maxDepth) {
754:         this.data.maxDepth = depth;
755:         if (this.player.onGround && depth > 1.5) {
756:           this.data.checkpoint = { x: this.player.pos.x, y: this.player.pos.y, z: this.player.pos.z };
757:         }
758:       }
759:       this.checkMilestones();
760:       this.particles.update(dt);
761:       this.env.update(dt, this.player.pos, depth);
762:       this.updateInteraction();
763:       this.updateHudFrame(dt, depth);
764:       this.saveTimer += dt;
765:       if (this.saveTimer > 9 && this.needSave) {
766:         this.saveTimer = 0;
767:         this.saveGame();
768:       }
769:       if (Math.abs(depth - this.lastAudioDepth) > 1.5) {
770:         this.lastAudioDepth = depth;
771:         this.audio.setDepth(depth);
772:       }
773:     } else {
774:       this.particles.update(dt);
775:       const depth = this.player ? this.player.getDepth() : 0;
776:       this.env.update(dt, this.player ? this.player.pos : this.camera.position, depth);
777:       this.updateHudFrame(dt, depth);
778:     }
779: 
780:     this.renderer.render(this.scene, this.camera);
781:   }
782: 
783:   updateHudFrame(dt, depth) {
784:     this.hudTimer -= dt;
785:     if (this.hudTimer <= 0) {
786:       this.hudTimer = 0.08;
787:       this.ui.updateHUD(this);
788:       const p = this.player;
789:       if (p.mining.active) this.ui.setCrosshair('mining', p.mining.progress);
790:       else if (p.outline.visible) this.ui.setCrosshair('target', 0);
791:       else this.ui.setCrosshair('none', 0);
792:     }
793:     if (!this.data.won && this.data.maxDepth >= 40) {
794:       const cp = this.world.corePos;
795:       const dx = cp.x - this.player.pos.x;
796:       const dz = cp.z - this.player.pos.z;
797:       const dy = cp.y - (this.player.pos.y + 1.6);
798:       const dist = Math.hypot(dx, dy, dz);
799:       const fx = -Math.sin(this.player.yaw), fz = -Math.cos(this.player.yaw);
800:       const rx = Math.cos(this.player.yaw), rz = -Math.sin(this.player.yaw);
801:       const len = Math.hypot(dx, dz) || 1;
802:       const angle = Math.atan2((dx / len) * rx + (dz / len) * rz, (dx / len) * fx + (dz / len) * fz) * 180 / Math.PI;
803:       this.ui.setSignal(true, dist, angle);
804:     } else {
805:       this.ui.setSignal(false, 0, 0);
806:     }
807:     this.ui.setDepthTint(depth);
808:   }
809: 
810:   updateInteraction() {
811:     this.interactTimer -= 0.016;
812:     if (this.interactTimer > 0) return;
813:     this.interactTimer = 0.12;
814:     const item = this.getInteractable();
815:     this.interactable = item;
816:     this.ui.setPrompt(item ? item.label : null);
817:   }
818: }
