850:     game.data.checkpoint = { x: 32.5, y, z: 38.5 };
851:     game.player.lampMix = 1;
852:   },
853:   carve(cx, cy, cz, rx, ry, rz) {
854:     for (let x = cx - rx; x <= cx + rx; x++) {
855:       for (let y = cy - ry; y <= cy + ry; y++) {
856:         for (let z = cz - rz; z <= cz + rz; z++) {
857:           if (x < 1 || x >= WORLD_X - 1 || z < 1 || z >= WORLD_Z - 1 || y < 2 || y >= WORLD_Y - 1) continue;
858:           game.world.set(x, y, z, 0);
859:         }
860:       }
861:     }
862:   },
863:   poseUnderground(depth = 42) {
864:     const y = Math.floor(SURFACE + 1 - depth);
865:     this.carve(32, y + 1, 32, 3, 2, 3);
866:     // decorate the walls with a few ores for the camera
867:     const ores = [BLOCK.GOLD, BLOCK.DIAMOND, BLOCK.IRON, BLOCK.RUBY, BLOCK.GOLD];
868:     let i = 0;
869:     for (let x = 28; x <= 36; x += 2) {
870:       for (let yy = y; yy <= y + 3; yy += 2) {
871:         game.world.set(x, yy, 28, ores[i % ores.length]);
872:         game.world.set(36 - (x - 28), yy, 36, ores[(i + 2) % ores.length]);
873:         i++;
874:       }
875:     }
876:     for (let z = 29; z <= 35; z += 3) {
877:       game.world.set(28, y + 2, z, ores[(z + i) % ores.length]);
878:       game.world.set(36, y + 2, z, ores[(z + i + 1) % ores.length]);
879:     }
880:     game.world.flushDirty();
881:     game.player.teleport(32.5, y + 1, 34.5);
882:     game.player.yaw = 0;
883:     game.player.pitch = -0.03;
884:     game.player.enabled = true;
885:     game.player.lampMix = 1;
886:     game.mode = 'playing';
887:     game.ui.showGame();
888:     game.data.maxDepth = Math.max(game.data.maxDepth, depth);
889:     game.data.checkpoint = { x: 32.5, y: y + 1, z: 34.5 };
890:     game.ui.updateHUD(game);
891:   },
892:   poseSurface() {
893:     const s = game.surfaceSpawn();
894:     game.player.teleport(s.x, s.y, s.z);
895:     game.player.yaw = 0;
896:     game.player.pitch = -0.13;
897:     game.player.enabled = true;
898:     game.mode = 'playing';
899:     game.ui.showGame();
900:     game.ui.updateHUD(game);
901:   },
902:   fillInventory() {
903:     game.data.inventory = {
