905:       [BLOCK.COPPER]: 9,
906:       [BLOCK.IRON]: 6,
907:       [BLOCK.GOLD]: 4,
908:       [BLOCK.DIAMOND]: 2,
909:       [BLOCK.RUBY]: 1,
910:       [BLOCK.DIRT]: 12,
911:     };
912:     game.ui.updateHUD(game);
913:   },
914:   setMoney(n) { game.data.money = n; game.ui.updateHUD(game); },
915:   grant(id, level) { game.data.upgrades[id] = level; game.ui.updateHUD(game); },
916:   openShop(tab = 'sell') {
917:     game.mode = 'playing';
918:     game.player.enabled = true;
919:     game.openShop(tab);
920:   },
921:   closeShop() { game.closeShop(); },
922:   sell() { game.sellAll(); },
923:   buy(id) { game.buyUpgrade(id); },
924:   win() { game.triggerWin(); },
925:   save() { game.saveGame(); },
926:   getPlayer() { return game.player; },
927: };

